cpu_set_t cpuset;
int target_core = 1; // Core ID to pin to

// 1. Initialize CPU set
CPU_ZERO(&cpuset);
// 2. Add the desired core to the set
CPU_SET(target_core, &cpuset);

// 3. Apply affinity using sched_setaffinity
// Target PID 0 (current process)
int result = sched_setaffinity(
    0, 
    sizeof(cpu_set_t), 
    &cpuset
);

// If successful, the process prefers target_core 1.

/* Thread Affinity (HPC context) */
pthread_t thread = pthread_self();
// CPU_ZERO & CPU_SET definitions omitted for brevity

int err = pthread_setaffinity_np(
    thread,
    sizeof(cpu_set_t),
    &cpuset
);
